package com.aether.launcher.settings

import android.content.Context
import android.graphics.Color
import android.view.Gravity
import android.widget.*
import kotlin.math.roundToInt

class AetherSetupView(context:Context,private val onFinished:()->Unit):ScrollView(context){
 private val store=AetherSettingsStore(context);private var s=store.load();private val root=LinearLayout(context).apply{orientation=LinearLayout.VERTICAL;setPadding(dp(24),dp(30),dp(24),dp(30));setBackgroundColor(0xFF080A0E.toInt())};private var page=0
 private val titles=listOf("Welcome","Home","Grid","Appearance","Dock","Dynamic Island","Quick Space","Control Center","Multitasking","Security","Ready")
 init{setFillViewport(true);addView(root);render()}
 private fun render(){root.removeAllViews();root.addView(TextView(context).apply{text="AETHER  •  ${page+1}/${titles.size}";textSize=11f;setTextColor(0x99FFFFFF.toInt())},lp(-1,34));root.addView(TextView(context).apply{text=titles[page];textSize=30f;setTextColor(Color.WHITE);typeface=android.graphics.Typeface.DEFAULT_BOLD;setPadding(0,dp(12),0,dp(8))},lp(-1,-2));root.addView(TextView(context).apply{text=subtitle();textSize=14f;setTextColor(0xBFFFFFFF.toInt());setPadding(0,0,0,dp(18))},lp(-1,-2));when(page){0->note("A calm Android home with real apps, live widgets, Quick Space, Dynamic Island and system-backed controls.");1->choice("Home mode",HomeMode.values().toList(),s.homeMode){s=s.copy(homeMode=it);save()};2->{seek("Columns",3,7,s.grid.columns){s=s.copy(grid=s.grid.copy(columns=it));save()};seek("Rows",4,9,s.grid.rows){s=s.copy(grid=s.grid.copy(rows=it));save()};seek("Icon size",40,72,s.grid.iconSize){s=s.copy(grid=s.grid.copy(iconSize=it));save()};toggle("App labels",s.grid.showLabels){s=s.copy(grid=s.grid.copy(showLabels=it));save()}};3->{choice("Theme",AppearanceTheme.values().toList(),s.appearance.theme){s=s.copy(appearance=s.appearance.copy(theme=it));save()};seek("Glass opacity",45,100,s.glass.opacity){s=s.copy(glass=s.glass.copy(opacity=it));save()};seek("Glass blur",0,50,s.glass.blur){s=s.copy(glass=s.glass.copy(blur=it));save()};choice("Motion",MotionPreset.values().toList(),s.motion.preset){s=s.copy(motion=s.motion.copy(preset=it));save()}};4->{toggle("Dock enabled",s.dock.enabled){s=s.copy(dock=s.dock.copy(enabled=it));save()};seek("Dock favorites",3,8,s.dock.appCount){s=s.copy(dock=s.dock.copy(appCount=it));save()}};5->{toggle("Dynamic Island",s.island.enabled){s=s.copy(island=s.island.copy(enabled=it));save()};toggle("Cutout aware",s.island.cutoutAware){s=s.copy(island=s.island.copy(cutoutAware=it));save()};seek("Island width",72,180,s.island.width){s=s.copy(island=s.island.copy(width=it));save()}};6->{toggle("Quick Space",s.quickSpace.enabled){s=s.copy(quickSpace=s.quickSpace.copy(enabled=it));save()};choice("Edge",QuickEdge.values().toList(),s.quickSpace.edge){s=s.copy(quickSpace=s.quickSpace.copy(edge=it));save()}};7->{toggle("Control Center",s.controlCenter.enabled){s=s.copy(controlCenter=s.controlCenter.copy(enabled=it));save()};seek("Tile columns",1,4,s.controlCenter.columns){s=s.copy(controlCenter=s.controlCenter.copy(columns=it));save()}};8->{toggle("Floating windows",s.floatingWindows.enabled){s=s.copy(floatingWindows=s.floatingWindows.copy(enabled=it));save()};toggle("Split screen",s.splitScreen.enabled){s=s.copy(splitScreen=s.splitScreen.copy(enabled=it));save()}};9->{toggle("App Lock",s.security.appLockEnabled){s=s.copy(security=s.security.copy(appLockEnabled=it));save()};toggle("Relock when leaving",s.security.relockOnLeave){s=s.copy(security=s.security.copy(relockOnLeave=it));save()};toggle("Use biometrics",s.security.useBiometrics){s=s.copy(security=s.security.copy(useBiometrics=it));save()}};10->note("Your choices are saved. Every section remains editable in Aether Settings.")}
 val nav=LinearLayout(context).apply{gravity=Gravity.CENTER_VERTICAL;setPadding(0,dp(22),0,0)};if(page>0)nav.addView(button("Back"){page--;render()},lp(0,56,1f).also{it.marginEnd=dp(10)});nav.addView(button(if(page==titles.lastIndex)"Enter Aether" else "Continue"){if(page==titles.lastIndex){store.save(s.copy(setupComplete=true));onFinished()}else{page++;render()}},lp(0,56,1f));root.addView(nav)}
 private fun save(){store.save(s)};private fun subtitle()=when(page){0->"Set up once. Everything remains editable.";1->"Choose your home model.";2->"Tune density, rows and icons.";3->"Shape Aether's visual material.";4->"Choose dock behavior.";5->"Tune live activity behavior.";6->"Configure the edge shortcut.";7->"Configure system-backed controls.";8->"Use Android's supported multi-window behavior.";9->"Protect selected apps.";else->"Aether is ready."}
 private fun note(v:String){root.addView(TextView(context).apply{text=v;textSize=16f;setTextColor(0xDFFFFFFF.toInt());setPadding(dp(20),dp(24),dp(20),dp(24));setBackgroundColor(0x181F2933)})}
 private fun button(v:String,a:()->Unit)=Button(context).apply{text=v;setTextColor(Color.WHITE);setOnClickListener{a()}}
 private fun toggle(label:String,value:Boolean,a:(Boolean)->Unit){val r=LinearLayout(context).apply{gravity=Gravity.CENTER_VERTICAL};r.addView(TextView(context).apply{text=label;textSize=15f;setTextColor(Color.WHITE)},lp(0,56,1f));r.addView(Switch(context).apply{isChecked=value;setOnCheckedChangeListener{_,v->a(v)}},lp(70,52));root.addView(r)}
 private fun seek(label:String,min:Int,max:Int,value:Int,a:(Int)->Unit){val box=LinearLayout(context).apply{orientation=LinearLayout.VERTICAL;setPadding(0,dp(6),0,dp(6))};val row=LinearLayout(context).apply{gravity=Gravity.CENTER_VERTICAL};val out=TextView(context).apply{text=value.toString();textSize=12f;setTextColor(0xBFFFFFFF.toInt());gravity=Gravity.END};row.addView(TextView(context).apply{text=label;textSize=15f;setTextColor(Color.WHITE)},lp(0,30,1f));row.addView(out,lp(56,30));val bar=SeekBar(context).apply{this.max=max-min;progress=(value-min).coerceIn(0,this.max);setOnSeekBarChangeListener(object:SeekBar.OnSeekBarChangeListener{override fun onProgressChanged(sb:SeekBar?,p:Int,fromUser:Boolean){val n=p+min;out.text=n.toString();if(fromUser)a(n)};override fun onStartTrackingTouch(sb:SeekBar?){ };override fun onStopTrackingTouch(sb:SeekBar?){ }})};box.addView(row);box.addView(bar);root.addView(box)}
 private fun <E:Enum<E>> choice(label:String,values:List<E>,selected:E,a:(E)->Unit){val row=LinearLayout(context).apply{gravity=Gravity.CENTER_VERTICAL};row.addView(TextView(context).apply{text=label;textSize=15f;setTextColor(Color.WHITE)},lp(0,56,1f));val sp=Spinner(context);sp.adapter=ArrayAdapter(context,android.R.layout.simple_spinner_dropdown_item,values.map{it.name.replace('_',' ').lowercase().replaceFirstChar{c->c.uppercase()}});sp.setSelection(values.indexOf(selected));sp.onItemSelectedListener=object:AdapterView.OnItemSelectedListener{override fun onItemSelected(p:AdapterView<*>?,v:android.view.View?,pos:Int,id:Long){a(values[pos])};override fun onNothingSelected(p:AdapterView<*>?){}};row.addView(sp,lp(190,56));root.addView(row)}
 private fun lp(w:Int,h:Int,weight:Float=0f)=LinearLayout.LayoutParams(if(w==0)0 else dp(w),if(h<0)-1 else dp(h),weight);private fun dp(v:Int)= (v*resources.displayMetrics.density).roundToInt()
}
